package io.github.long0823.tclviewer;
import android.app.Instrumentation;import android.os.Bundle;
public class PairingTest extends Instrumentation {private String host,pin;public void onCreate(Bundle b){super.onCreate(b);host=b.getString("host");pin=b.getString("pin");start();}public void onStart(){Bundle out=new Bundle();try{ChannelConfig c=PairingClient.fetch(host,pin);c.tuner=0;getTargetContext().getSharedPreferences("MainActivity",0).edit().putString("profile",c.toIni()).commit();out.putInt("channels",c.channels.size());out.putBoolean("iptv_available",!c.iptvAccessCode.isEmpty());out.putBoolean("native_credential_not_in_iptv_url",!c.iptvPlaylistUrl().contains(c.token));out.putBoolean("network_keepalive_configured",c.networkKeepalive);out.putString("result","PASS");finish(-1,out);}catch(Exception e){out.putString("result","FAIL "+e.getClass().getSimpleName()+": "+e.getMessage());finish(0,out);}}}